//! TEMPORARY measurement instrumentation (audit only; never committed).
use std::hash::{Hash, Hasher};
use std::sync::Mutex;
use std::time::Instant;

use rustc_hash::FxHashMap;

#[derive(Default)]
struct Cache {
    starts: u64,
    inflight_other: u64,
    inflight_same: u64,
    done_other: u64,
    done_same: u64,
    total_ns: u128,
    dup_ns: u128,
    inflight: FxHashMap<u64, (u32, u64)>,
    done: FxHashMap<u64, u64>,
}

static CACHES: Mutex<Option<FxHashMap<&'static str, Cache>>> = Mutex::new(None);

pub fn owner() -> u64 {
    let mut h = rustc_hash::FxHasher::default();
    std::thread::current().id().hash(&mut h);
    h.finish()
}

pub struct Guard {
    cache: &'static str,
    key: u64,
    owner: u64,
    dup: bool,
    at: Instant,
}

pub fn start<K: Hash>(cache: &'static str, key: &K, owner: u64) -> Guard {
    let mut h = rustc_hash::FxHasher::default();
    key.hash(&mut h);
    let key = h.finish();
    let mut guard = CACHES.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    let c = guard.get_or_insert_with(Default::default).entry(cache).or_default();
    c.starts += 1;
    let mut dup = false;
    if let Some((_, o)) = c.inflight.get(&key) {
        dup = true;
        if *o == owner {
            c.inflight_same += 1;
        } else {
            c.inflight_other += 1;
        }
    } else if let Some(o) = c.done.get(&key) {
        dup = true;
        if *o == owner {
            c.done_same += 1;
        } else {
            c.done_other += 1;
        }
    }
    let e = c.inflight.entry(key).or_insert((0, owner));
    e.0 += 1;
    Guard { cache, key, owner, dup, at: Instant::now() }
}

impl Drop for Guard {
    fn drop(&mut self) {
        let ns = self.at.elapsed().as_nanos();
        let mut guard = CACHES.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let c = guard.get_or_insert_with(Default::default).entry(self.cache).or_default();
        c.total_ns += ns;
        if self.dup {
            c.dup_ns += ns;
        }
        if let Some(e) = c.inflight.get_mut(&self.key) {
            e.0 -= 1;
            if e.0 == 0 {
                c.inflight.remove(&self.key);
            }
        }
        c.done.entry(self.key).or_insert(self.owner);
    }
}

pub fn report() {
    let guard = CACHES.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    let Some(map) = guard.as_ref() else { return };
    let mut names: Vec<_> = map.keys().copied().collect();
    names.sort_unstable();
    for n in names {
        let c = &map[n];
        eprintln!(
            "DUP {n}: starts={} inflight_other={} inflight_same={} done_other={} done_same={} total_ms={} dup_ms={}",
            c.starts,
            c.inflight_other,
            c.inflight_same,
            c.done_other,
            c.done_same,
            c.total_ns / 1_000_000,
            c.dup_ns / 1_000_000
        );
    }
}
